import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione; il concetto di evento","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lca.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lca.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lca.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione-il-concetto-di-evento" tabindex="-1">Introduzione; il concetto di evento <a class="header-anchor" href="#introduzione-il-concetto-di-evento" aria-label="Permalink to “Introduzione; il concetto di evento”">​</a></h1><p>Introduciamo il concetto di evento:</p><p>Chiameremo <strong>evento</strong> il verificarsi di un certo insieme di condizioni derivate da un esperimento:</p><blockquote><p>Esperimento: lancio una volta un dado; evento: ottengo il numero <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>6</mn></mrow><annotation encoding="application/x-tex">6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span></p></blockquote><p>Parleremo di <strong>evento certo</strong> se l&#39;evento si verifica sempre</p><blockquote><p>Esperimento: sopra il mio tavolo lascio libera una matita in aria; Evento: essa cade sul tavolo</p></blockquote><p>Parleremo di <strong>evento impossibile</strong> se l&#39;evento non si verifica mai</p><blockquote><p>Esperimento: sopra il mio tavolo lascio libera una matita in aria; Evento: essa sale fino al soffitto</p></blockquote><p>Parleremo di <strong>evento aleatorio</strong> se l&#39;evento può verificarsi oppure no</p><blockquote><p>Esperimento: lancio una volta un dado; Evento: esce il numero <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span></p></blockquote><p>Diviene quindi naturale assegnare all&#39;evento aleatorio un numero che esprima la quantità di possibilità del verificarsi dell&#39;evento stesso:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mi>p</mi><mo>=</mo><mi>P</mi><mo stretchy="false">(</mo><mi>E</mi><mo stretchy="false">)</mo></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{p = P(E)} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="color:red;">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;color:red;">P</span><span class="mopen" style="color:red;">(</span><span class="mord mathnormal" style="margin-right:0.0576em;color:red;">E</span><span class="mclose" style="color:red;">)</span></span></span></span></span></p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi></mrow><annotation encoding="application/x-tex">p</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> è la probabilità che si verifichi l&#39;evento <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi></mrow><annotation encoding="application/x-tex">E</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span></p><blockquote><p><strong>Esempio:</strong> se <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>E</mi></mrow><annotation encoding="application/x-tex">E</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> è l&#39;evento uscita del numero <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> nel lancio di</p></blockquote>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};